const api=async(url,opt={})=>{const r=await fetch(url,{headers:{"Content-Type":"application/json"},...opt});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||"Une erreur est survenue");return j};
const fmtDate=v=>v?new Date(v).toLocaleDateString("fr-FR",{weekday:"short",day:"2-digit",month:"short",year:"numeric"}):"—";
const fmtDateTime=v=>v?new Date(v).toLocaleString("fr-FR",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}):"—";
const cleanInfoKey=k=>String(k||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const hiddenInfoKeys=new Set(['country','timezone','full name','contact type','first name','last name','email','phone','telephone','location id','contact id','form id','form submission id','workflow','workflow name','attributionsource','attribution source','attribution source data','user agent','fbclid','gclid','type','app id','appid','timestamp','version id','versionid','webhook id','webhookid','dateadded','date added']);
const canonicalInfoKey=k=>{const n=cleanInfoKey(k);if(n==='date created'||n==='date de creation'||n==='date added')return 'date created';if(n==='contact source'||n==='source du contact')return 'contact source';return n};
const infoLabel=k=>{const n=canonicalInfoKey(k);if(n==='date created')return 'Date de création';if(n==='contact source')return 'Source du contact';return String(k||'').replace(/_/g,' ')};
const infoValue=(k,v)=>{const n=canonicalInfoKey(k),s=String(v??'');if(n==='date created'){const d=new Date(s);if(!Number.isNaN(d.getTime()))return d.toLocaleString('fr-FR',{timeZone:'Europe/Paris',day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'})}return s};
const visibleAdditionalInfo=info=>{const seen=new Map();for(const [k,v] of Object.entries(info||{})){const n=canonicalInfoKey(k),txt=String(v??'').trim();if(!n||!txt||hiddenInfoKeys.has(n)||n.startsWith('attribution source'))continue;if(!seen.has(n))seen.set(n,[k,v])}return [...seen.values()]};
const monthKey=v=>(v||"").slice(0,7);
const telHref=n=>n?`tel:${n}`:'#';
const waHref=n=>n?`https://wa.me/${String(n).replace(/\D/g,'')}`:'#';
const smsHref=n=>n?`sms:${n}`:'#';
const statusClass=s=>`status-pill status-${String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-')}`;
const hexToRgba=(hex,a=.12)=>{const h=String(hex||'#67707E').replace('#','');const v=h.length===3?h.split('').map(x=>x+x).join(''):h;const n=parseInt(v,16);return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`};
const rangeLabel=(start,end,mode)=>mode==='all'?'Toutes les données':`${new Date(start+'T12:00:00').toLocaleDateString('fr-FR')} → ${new Date(end+'T12:00:00').toLocaleDateString('fr-FR')}`;
const csvCell=v=>`"${String(v??'').replace(/"/g,'""')}"`;
function downloadCsv(filename,headers,rows){const content='\uFEFF'+[headers,...rows].map(row=>row.map(csvCell).join(';')).join('\r\n');const blob=new Blob([content],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
const submissionAnswerEntries=sub=>Object.entries(sub?.answers||{}).filter(([,v])=>String(v??'').trim());
const answerSummary=lead=>Array.isArray(lead.formSubmissions)&&lead.formSubmissions.length?lead.formSubmissions.map((sub,i)=>`Demande ${i+1} — ${sub.formName||'Formulaire GHL'} : ${submissionAnswerEntries(sub).map(([k,v])=>`${infoLabel(k)} : ${infoValue(k,v)}`).join(' | ')}`).join(' || '):visibleAdditionalInfo(lead.additionalInfo).map(([k,v])=>`${infoLabel(k)} : ${infoValue(k,v)}`).join(' | ');
const lastComment=lead=>{const c=(lead.comments||[]).at(-1);return c?.text||''};
