 useEffect(()=>{loadResources()},[client.id]);
 async function saveAssignments(){try{setBusy(true);setErr('');const chosenLocation=locations.find(x=>x.id===locationId);const chosenAccount=accounts.find(x=>x.id===adAccountId||x.accountId===adAccountId);let integrations=[...(state.integrations||[])];const nextGhl={...ghl,id:ghl.id||uid(),institutId:client.id,provider:'ghl',locationId,locationName:chosenLocation?.name||ghl.locationName||'',connected:Boolean(locationId),forms:ghl.forms||[],updatedAt:nowIso()};integrations=integrations.some(x=>x.id===ghl.id)?integrations.map(x=>x.id===ghl.id?nextGhl:x):[...integrations,nextGhl];if(adAccountId){const nextMeta={...(meta||{}),id:meta?.id||uid(),institutId:client.id,provider:'meta',connected:true,adAccountId:chosenAccount?.id||adAccountId,adAccountNumericId:chosenAccount?.accountId||String(adAccountId).replace(/^act_/,''),adAccountName:chosenAccount?.name||adAccountId,currency:chosenAccount?.currency||'EUR',campaignMappings:meta?.campaignMappings||[],updatedAt:nowIso()};integrations=meta?integrations.map(x=>x.id===meta.id?nextMeta:x):[...integrations,nextMeta]}else if(meta){integrations=integrations.map(x=>x.id===meta.id?{...x,connected:false,adAccountId:'',adAccountNumericId:'',adAccountName:'',updatedAt:nowIso()}:x)}await save({...state,integrations});setSaved(true);setTimeout(()=>setSaved(false),1800);await refresh()}catch(e){setErr(e.message)}finally{setBusy(false)}}
